/* Css cho mục Button Liên Hệ Ngay cho trang Liên Hệ */
button.btnFormContact {
    background: transparent; 
    border: none;           
    padding: 0;             
    cursor: pointer;
    width: auto;            
}
button.btnFormContact {
    background-color: #6a8d2e; 
    color: #fff;
    padding: 10px 20px;
    border-radius: 5px;
    transition: all 0.3s ease;
}
@keyframes bounceText {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-4px); } 
}
button.btnFormContact .btn-text {
    display: inline-block;
    font-weight: bold;
    text-transform: uppercase;
    animation: bounceText 2s infinite ease-in-out; 
}
button.btnFormContact:hover {
    opacity: 0.9;
}

