2023/02/zxcc.png","id":8721,"alt":"","source":"library"},"align":"center","width":{"unit":"%","size":15,"sizes":[]}},"elements":[],"widgetType":"image"},{"id":"b9ae257","elType":"widget","settings":{"title":"Đây là những bình luận của những khách hàng đã lựa chọn và sử dụng dịch vụ của Cửu Long Media","ucfont_title__fonts-enabled":"yes","ucfont_title__typography_typography":"custom","ucfont_title__typography_font_family":"Great Vibes","ucfont_title__typography_font_size":{"unit":"rem","size":1.3,"sizes":[]},"ucfont_title__typography_font_weight":"400","ucfont_title__color":"#C78665","_css_classes":"custom-p","ucfont_title__typography_font_size_tablet":{"unit":"rem","size":1.2,"sizes":[]},"ucfont_title__typography_font_size_mobile":{"unit":"rem","size":"","sizes":[]},"hide_tablet":"hidden-tablet","hide_mobile":"hidden-mobile"},"elements":[],"widgetType":"ucaddon_uc_scroll_reveal_text"},{"id":"fb79b98","elType":"widget","settings":{"number_of_items":1,"margin_between_slides":10,"show_arrows":"false","show_dots":"","layout":"column-reverse","show_subtitle":"","show_icon":"","show_rating":"true","nav_dots_size":{"unit":"px","size":6,"sizes":[]},"dot_color":"#FFFFFF","dot_active_color":"#6E6E6E","dot_spacing":{"unit":"px","size":10,"sizes":[]},"dot_space_between":{"unit":"px","size":5,"sizes":[]},"rating_color":"#C78665","uc_items":[{"title":"Thảo Nguyễn","subtitle":"New York","text":"Cảm ơn anh chị và ekip đã rất chu đáo chuẩn bị cho vợ chồng em, chụp ảnh mệt lắm rồi mà vẫn cứ phải cười vì ai cũng vui tính và hài hước. Cả thái độ và chất lượng bộ ảnh đều rất là ưng. Đúng là sự lựa chọn đúng đắn khi chọn Cửu Long Media","image":{"url":"https://truyenthongcuulong.com/wp-content/uploads/2023/02/user1.jpg","id":8168,"alt":"","source":"library"},"item_repeater_class":"elementor-repeater-item-h1q01","_id":"535d09a"},{"title":"Trà My","subtitle":"New York","text":"Gửi ngàn yêu thương tới Cửu Long Media, vợ chồng mình cảm thấy thật đúng đắn khi lựa chọn ekip của bạn để chụp bộ ảnh quan trọng nhất của cuộc đời. Cảm ơn các bạn vì đã rất nhiệt tình và có tâm. ","image":{"url":"https://truyenthongcuulong.com/wp-content/uploads/2023/02/user2_1.jpg","id":8169,"alt":"","source":"library"},"item_repeater_class":"elementor-repeater-item-uju0b","_id":"3042be8"},{"title":"Bích Phương","subtitle":"New York","text":"Cảm ơn Cửu Long Media đã chụp cho vợ chồng mình bộ ảnh cưới hoàn hảo. Cả ekip đều rất hài hước và chu đáo, mặc dù hôm đám cưới bận tiếp khách rất đông và rất mệt, nhưng lên hình vẫn tươi, một phần cũng nhờ sự hỗ trợ nhiệt tình từ các bạn. Đám xong chừng vài bữa là có hình, nhanh ghê. Mọi người trong gia đình xem xong album ảnh ai cũng khen đẹp hết.","image":{"url":"https://truyenthongcuulong.com/wp-content/uploads/2023/02/user3.jpg","id":8170,"alt":"","source":"library"},"item_repeater_class":"elementor-repeater-item-v0pci","_id":"7ab1103"},{"title":"Amber","subtitle":"New York","text":"Tôi thực sự không hài lòng với ekip chụp ảnh của Cửu Long Media, thái độ của nhân viên quá nhiệt tình, tôi không giỏi tạo dáng lắm nên thợ ảnh phải ra làm mẫu hướng dẫn. File ảnh nhận quá nhiều mà không xóa được tấm nào vì quá đẹp luôn đó. ","image":{"url":"https://truyenthongcuulong.com/wp-content/uploads/2023/02/user4.jpg","id":8171,"alt":"","source":"library"},"item_repeater_class":"elementor-repeater-item-mfult","_id":"0350d89"}],"_margin":{"unit":"px","top":"10","right":"0","bottom":"0","left":"0","isLinked":false},"title_typography_typography":"custom","title_typography_font_family":"Mulish","title_typography_font_weight":"bold","text_color":"#000000","text_typography_typography":"custom","text_typography_font_family":"Mulish","text_typography_font_weight":"400","_animation":"fadeInUp","border_radius":{"unit":"px","top":"20","right":"20","bottom":"20","left":"20","isLinked":true},"box_background_color":"","box_border_border":"none","_background_background":"classic","_background_image":{"url":"https://truyenthongcuulong.com/wp-content/uploads/2023/02/