:"https://truyenthongcuulong.com/wp-content/uploads/2023/02/zxcc.png","id":8721,"alt":"","source":"library"},"align":"center","width":{"unit":"%","size":15,"sizes":[]}},"elements":[],"widgetType":"image"},{"id":"a6ec86f","elType":"widget","settings":{"title":"Các câu hỏi Cửu Long Media thường gặp khi tư vấn cho khách hàng.","ucfont_title__fonts-enabled":"yes","ucfont_title__typography_typography":"custom","ucfont_title__typography_font_family":"Great Vibes","ucfont_title__typography_font_size":{"unit":"rem","size":1.3,"sizes":[]},"ucfont_title__typography_font_weight":"400","ucfont_title__color":"#C78665","_css_classes":"custom-p","ucfont_title__typography_font_size_tablet":{"unit":"rem","size":1.2,"sizes":[]},"ucfont_title__typography_font_size_mobile":{"unit":"rem","size":"","sizes":[]},"hide_tablet":"hidden-tablet","hide_mobile":"hidden-mobile"},"elements":[],"widgetType":"ucaddon_uc_scroll_reveal_text"}],"isInner":true}],"isInner":true},{"id":"49ad8de","elType":"section","settings":{"gap":"no","structure":"20","margin":{"unit":"px","top":"30","right":0,"bottom":"0","left":0,"isLinked":false},"animation":"fadeInUp"},"elements":[{"id":"87c9830","elType":"column","settings":{"_column_size":50,"_inline_size":null},"elements":[{"id":"bfc888f","elType":"widget","settings":{"tabs":[{"tab_title":"Trong các gói chụp ảnh có kèm váy cưới, trang điểm hay không?","tab_content":"<p>Cửu Long Media là đơn vị chuyên về chụp ảnh, quay phim sự kiện cưới hỏi. Chúng tôi muốn tập trung vào chuyên môn của mình để mang đến sự chuyên nghiệp và chỉn chu trong từng sản phẩm. Vì vậy, Cửu Long Media không cung cấp bất kì dịch vụ nào khác ngoài quay chụp để đảm bảo sự hài lòng cho các cặp đôi trong ngày trọng đại nhất của mình.</p>","_id":"7f13d26"},{"tab_title":"Có thể chụp và quay theo ý của cặp đôi hay không?","tab_content":"<p>Cô dâu và chú rể có thể trao đổi tất cả ý tưởng của mình với Cửu Long Media trước ngày buổi lễ diễn ra. Việc trao đổi thoải mái giữa đôi bên giúp chúng tôi hiểu rõ mong muốn của cặp đôi và tư vấn kịp thời để cùng tạo ra thành phẩm hoàn hảo nhất theo đúng những ý tưởng của đôi uyên ương. Cửu Long Media mong rằng, bất kì cặp đôi nào đến với chúng tôi có thể lưu giữ khoảnh khắc đẹp nhất trong lễ cưới - hỏi, đồng thời đây sẽ là tác phẩm " có 1 - 0 - 2" mang đậm dấu ấn riêng của cả hai và đồng thời bắt kịp xu hướng mới nhất.</p>","_id":"a39746c"},{"tab_title":"Làm sao để chọn lựa được Photographer phù hợp?","tab_content":"<p>Nhiều cặp đôi thường lo sợ người thợ chụp ảnh sẽ không hiểu ý của mình khi tác nghiệp, bỏ lỡ những khoảnh khắc đẹp nhất, bộ ảnh hay video cưới của mình không thật sự bắt mắt, ... Tất cả những điều này sẽ được đơn giản hóa khi bạn chọn Cửu Long Media làm đơn vị đồng hành trong ngày trọng đại. Chúng tôi cam kết thành phẩm được tạo ra phải là những bức ảnh, những thước phim đẹp và ý nghĩa nhất đối với cô dâu chú rể và cả những người thân, bạn bè.</p>","_id":"493ada5"}],"selected_icon":{"value":"fas fa-chevron-down","library":"fa-solid"},"selected_active_icon":{"value":"fas fa-chevron-up","library":"fa-solid"},"title_color":"#121F38","tab_active_color":"#000000","content_color":"#000000","title_typography_typography":"custom","title_typography_font_family":"Mulish","title_typography_font_size":{"unit":"px","size":18,"sizes":[]},"title_typography_font_weight":"bold","content_typography_typography":"custom","content_typography_font_family":"Mulish","content_typography_font_size":{"unit":"px","size":14,"sizes":[]},"content_typography_font_weight":"400"},"elements":[],"widgetType":"accordion"}],"isInner":true},{"id":"719c5dc","elType":"column","settings":{"_column_size":50,"_inline_size":null,"padding":{"unit":"px","top":"10","right":"10","bottom":"10","left":"10","isLinked":true}},"elements":[{"id":"1cad3e3","elType":"widget","settings":{"image":{"url":"https://truyenthongcuulong.com/wp-content/uploads/2023/02/img-cau-hoi-thuong-gap-1.jpg","id":8399,"alt":"","source":"library"},"title":"Blob Title","text":"Lorem ipsu