a:7:{s:8:"metadata";a:5:{s:4:"type";s:8:"template";s:9:"shortcode";s:38:"s-e5fadfa7-d6e8-43f6-9a7b-6efcc93b33af";s:9:"isPrimary";s:0:"";s:5:"title";s:3:"FAQ";s:23:"reviewLocationShortcode";s:24:"[rank_math_rich_snippet]";}s:5:"@type";s:7:"FAQPage";s:4:"name";s:11:"%seo_title%";s:3:"url";s:5:"%url%";s:13:"datePublished";s:20:"%date(Y-m-dTH:i:sP)%";s:12:"dateModified";s:24:"%modified(Y-m-dTH:i:sP)%";s:10:"mainEntity";a:3:{i:0;a:3:{s:5:"@type";s:8:"Question";s:4:"name";s:74:"Giá trọn gói đã bao gồm chi phí đi lại trong Cần Thơ chưa?";s:14:"acceptedAnswer";a:2:{s:5:"@type";s:6:"Answer";s:4:"text";s:296:"Có. Tất cả các gói dịch vụ của Cửu Long Media đã bao gồm chi phí đi lại trong nội ô thành phố Cần Thơ. Đối với các quận huyện ngoại thành hoặc các tỉnh lân cận, chúng tôi sẽ có một khoản phụ phí nhỏ và báo trước cho bạn.

";}}i:1;a:3:{s:5:"@type";s:8:"Question";s:4:"name";s:81:"Sau bao lâu kể từ sự kiện thì tôi nhận được ảnh hoàn chỉnh?";s:14:"acceptedAnswer";a:2:{s:5:"@type";s:6:"Answer";s:4:"text";s:295:"Thời gian giao ảnh đầy đủ thường từ 3-5 ngày làm việc. Tuy nhiên, với Gói Chuyên Nghiệp và Cao Cấp, Cửu Long Media sẽ hỗ trợ giao một số lượng ảnh nổi bật chỉ sau 24 giờ để phục vụ nhu cầu truyền thông tức thời của bạn.

";}}i:2;a:3:{s:5:"@type";s:8:"Question";s:4:"name";s:82:"Ngoài chụp ảnh, Cửu Long Media có cung cấp dịch vụ quay phim không?";s:14:"acceptedAnswer";a:2:{s:5:"@type";s:6:"Answer";s:4:"text";s:213:"Chắc chắn có. Chúng tôi là một công ty truyền thông đa phương tiện. Việc kết hợp cả hai dịch vụ sẽ giúp bạn có một gói media sự kiện toàn diện và tối ưu chi phí.";}}}}

